head.script:
scwin.clickCheckBox = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id).childNodes[0].click();
}
scwin.isChecked = function() {
    var el = WebSquare.wUnit.getDomById($p.id + 'gridView1_column5').childNodes[0];
    return el.checked == false;
}
scwin.checktype = function() {
    return typeof WebSquare.wUnit.getObjById('gridView1_column5').childNodes[0] === 'object';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5').setAttribute('usePartialCheck', 'false')");
    // verify step 0. usePartialCheck='false'
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_column5').getAttribute('usePartialCheck') == 'false'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플파일을 실행 후 gridView의 체크박스 한개를 클릭한다
    //1. After running the sample file, click on one of the gridView checkboxes.
    WebSquare.wUnit.addCommand("set", "scwin.clickCheckBox('gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.isChecked()", "true");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    dataList1.setData(["", "", "", "", "", ""]);
}
